// Geography lessons — loaded on demand by ensureLessons('geography') in index.html.
// Shape: LESSON_DB.geography.m<moduleIndex>[topicIndex] = lesson. Order matches COURSE_DATA.geography.
// Three lessons (m0[0], m1[0], m3[0]) are hand-written inside index.html; _geoAdd merges the parts
// they were missing (hook, examples, mistakes, quiz, illustration) into them instead of replacing them.
// Statistics are rounded and dated where they matter — check current figures for projects.
LESSON_DB.geography = LESSON_DB.geography || {};
function _geoAdd(m, lessons){ LESSON_DB.geography[m] = LESSON_DB.geography[m] || {}; Object.keys(lessons).forEach(function(i){ LESSON_DB.geography[m][i] = Object.assign(LESSON_DB.geography[m][i] || {}, lessons[i]); }); }

// ─── Module 0: Climate & Weather ────────────────────────────────────────────
_geoAdd('m0', {
  0: {subtitle:"Grade 11 · The forces that drive our weather",
    hook:{title:"Winter rain in Cape Town, summer storms in Joburg", body:"Cape Town gets most of its rain in winter; Johannesburg gets afternoon thunderstorms in summer and almost no rain in winter. Same country, opposite seasons. The reason is a giant pattern of rising and sinking air that circles the whole planet — and South Africa sits right at the edge of it."},
    examples:[
      {title:"Why deserts near 30°?", body:"Why are the Kalahari and Namib deserts found near latitude 30°S?", answer:"Air that rose at the equator <strong>sinks</strong> at about 30° (the Hadley cell). Sinking air warms and dries, creating <strong>subtropical high pressure</strong> — few clouds, little rain."},
      {title:"Highveld summer storms", body:"Why does the Highveld get thunderstorms on summer afternoons?", answer:"Strong summer heating causes <strong>convection</strong>. Moist air pushed inland from the Indian Ocean high rises, cools and condenses into cumulonimbus clouds."},
      {title:"Cape winter rain", body:"Why does the Western Cape get rain in winter?", answer:"In winter the pressure belts <strong>shift north</strong> with the sun, so mid-latitude cyclones and their <strong>cold fronts</strong> in the westerlies reach the south-western Cape."},
    ],
    mistakes:["Mixing up high pressure (sinking, dry) and low pressure (rising, wet).","Saying wind blows from low to high pressure — it blows from high to low.","Forgetting that the Coriolis force deflects winds to the <strong>left</strong> in the Southern Hemisphere."],
    activityAnswer:"Look for the H (anticyclones) over the oceans and interior, cold fronts as lines with triangles south of the country, and wind arrows blowing from high to low and deflected left. A cold front approaching Cape Town means wind, rain and cooler weather there within 24–48 hours; Johannesburg in winter under a high will stay dry, sunny and cold at night.",
    quiz:[
      {q:"Air at the subtropical high-pressure belt (about 30°) is:",opts:["Rising","Sinking","Stationary","Freezing"],a:1,et:"Sinking air warms and dries — deserts form here."},
      {q:"In the Southern Hemisphere, the Coriolis force deflects winds to the:",opts:["Right","Left","North only","Not at all"],a:1,et:"Left in the south, right in the north."},
      {q:"The south-western Cape gets most of its rain in:",opts:["Summer","Winter","Only in spring","Equally all year"],a:1,et:"Cold fronts reach it when pressure belts shift north in winter."},
    ],
    conclusion:"South Africa's weather is decided far away — by belts of rising and sinking air that shift with the seasons."},

  1: {emoji:"🌀", subtitle:"Grade 11–12 · Reading highs, lows and isobars",
    illusText:"A big “H” over the interior in winter means clear skies by day — and frost by night.",
    hook:{title:"Frost on the Highveld", body:"On a July weather map, a large <strong>H</strong> sits over the interior. The forecast: sunny, dry and below zero overnight in Bloemfontein and Johannesburg. High pressure means sinking air and clear skies — and with no cloud blanket at night, the ground loses its heat fast. Reading pressure systems lets you forecast like a meteorologist."},
    intro:"<strong>Air pressure</strong> is the weight of the air above a point, measured in hectopascals (hPa); average sea-level pressure is about 1013 hPa. <strong>Isobars</strong> join places of equal pressure. A <strong>high-pressure system (anticyclone)</strong> has sinking, diverging air, clear skies and light winds; in the Southern Hemisphere it circulates <strong>anticlockwise</strong>. A <strong>low-pressure system (cyclone/depression)</strong> has rising, converging air, clouds and often rain; it circulates <strong>clockwise</strong> in the Southern Hemisphere. Wind blows from high to low pressure, and the closer the isobars, the stronger the wind.",
    concepts:[
      {t:"green", title:"⬇️ Anticyclones", body:"Sinking air warms and dries → clear skies, stable weather, cold nights in winter. Semi-permanent highs sit over the South Atlantic, the South Indian Ocean and (in winter) the interior."},
      {t:"teal", title:"⬆️ Cyclones / lows", body:"Rising air cools → condensation → clouds and rain. Heat lows form over the hot interior in summer; coastal lows move along the coast."},
      {t:"gold", title:"📏 Pressure gradient", body:"Isobars close together = steep pressure gradient = strong winds. Widely spaced isobars = calm conditions."},
    ],
    examples:[
      {title:"Which way does it turn?", body:"How does air circulate around a high and a low in the Southern Hemisphere?", answer:"High: <strong>anticlockwise</strong>. Low: <strong>clockwise</strong>. (The opposite of the Northern Hemisphere.)"},
      {title:"Reading isobars", body:"Isobars are packed tightly over the Eastern Cape coast. What should the forecast say?", answer:"A steep pressure gradient means <strong>strong to gale-force winds</strong> along that coast."},
      {title:"Why frost?", body:"Why do winter highs over the interior cause frost?", answer:"Sinking air gives <strong>clear skies</strong>; at night there's no cloud to trap heat, so the ground cools rapidly below freezing."},
    ],
    mistakes:["Using Northern Hemisphere rotation (clockwise highs) for South African maps.","Thinking high pressure always means hot weather — in winter it means cold, clear nights.","Saying close isobars mean rain — they mean strong wind."],
    callout:{title:"Read a synoptic map", body:"The South African Weather Service publishes daily synoptic charts. Practise finding the highs, lows, fronts and the 1013 hPa isobar."},
    activity:"Isobars on a map are labelled 1024, 1020, 1016 and 1012 hPa from the interior towards the coast. Where is the high, which way does the wind blow, and where is it strongest?",
    activityAnswer:"The high is over the <strong>interior</strong> (1024 hPa). Wind blows from the interior towards the coast (high to low), circulating anticlockwise and deflected left. It is strongest where the isobars are <strong>closest together</strong>.",
    examTip:"When describing a pressure system, give the pressure, the air movement (sinking/rising), the rotation direction for the Southern Hemisphere and the weather it brings.",
    keyterms:[{w:"Isobar",d:"A line joining places of equal air pressure"},{w:"Anticyclone",d:"A high-pressure system with sinking air"},{w:"Pressure gradient",d:"The rate of change of pressure over distance"}],
    quiz:[
      {q:"In the Southern Hemisphere, an anticyclone circulates:",opts:["Clockwise","Anticlockwise","Straight north","It doesn't move"],a:1,et:"Highs turn anticlockwise in the south."},
      {q:"Isobars close together indicate:",opts:["Calm weather","Strong winds","Snow","High temperature"],a:1,et:"A steep pressure gradient drives strong winds."},
      {q:"Rising air is associated with:",opts:["High pressure and clear skies","Low pressure and clouds","Frost","Desert conditions"],a:1,et:"Rising air cools and condenses."},
    ],
    conclusion:"Highs bring calm and clear skies, lows bring clouds and rain — and the isobars tell you how windy it will be."},

  2: {emoji:"🌦️", subtitle:"Grade 11–12 · Cold fronts, berg winds and line thunderstorms",
    illusText:"When a cold front meets a cut-off low, the N3 at Van Reenen's Pass can close for snow.",
    hook:{title:"Snow on the N3", body:"Every few winters, trucks queue for hours at Van Reenen's Pass because snow has closed the N3 between Durban and Johannesburg. Behind it is a strong <strong>cold front</strong> pushing icy polar air far north. Southern Africa's weather is a cast of recurring characters — cold fronts, berg winds, line thunderstorms and coastal lows. Learn them and the weather map tells a story."},
    intro:"<strong>Mid-latitude cyclones</strong> move from west to east south of the country; their <strong>cold fronts</strong> bring winter rain to the south-western Cape and snow to high ground. <strong>Line thunderstorms</strong> form in summer along a <strong>moisture front</strong> where moist air from the east meets dry air from the west. <strong>Berg winds</strong> are hot, dry winds blowing offshore from the interior plateau down the escarpment, warming as they descend — a fire risk. <strong>Coastal lows</strong> move along the coast and often come before cold fronts.",
    concepts:[
      {t:"green", title:"❄️ Cold front sequence", body:"Before: warm, north-westerly winds, falling pressure. During: cloud, rain, wind shift to south-west, temperature drop. After: cold, clear, rising pressure."},
      {t:"teal", title:"⛈️ Line thunderstorms", body:"Moist easterly air meets dry westerly air along a line across the interior — storms form in a long line on summer afternoons."},
      {t:"gold", title:"🔥 Berg winds", body:"Air sinking from the plateau warms by compression. Berg winds bring hot, dry days on the coast in winter and raise the risk of veld fires."},
    ],
    examples:[
      {title:"Cold front forecast", body:"A cold front reaches Cape Town tonight. Describe the weather tomorrow afternoon after it passes.", answer:"<strong>Cold, clearing skies, south-westerly wind, rising pressure</strong> — the rain falls as the front passes."},
      {title:"Berg wind day", body:"Why can Durban reach 35 °C on a winter's day?", answer:"A <strong>berg wind</strong>: air from the interior high sinks down the escarpment, warms by compression and blows offshore — hot and dry."},
      {title:"Moisture front", body:"Where do line thunderstorms form?", answer:"Along the <strong>moisture front</strong> where moist air from the east meets dry air from the west over the interior."},
    ],
    mistakes:["Saying cold fronts bring summer rain to the Highveld.","Describing berg winds as cold — they are hot and dry.","Getting the before/during/after sequence of a cold front mixed up."],
    callout:{title:"Safety", body:"Berg winds and dry winter vegetation create extreme fire danger. Snow and cold fronts bring livestock losses and dangerous roads — warnings save lives."},
    activity:"Draw a timeline for Cape Town as a cold front passes: write the wind direction, temperature, pressure and weather before, during and after.",
    activityAnswer:"Before: north-westerly wind, mild, pressure falling, cloud increasing. During: wind veers south-westerly, rain, temperature drops. After: south-westerly wind, cold and clear, pressure rising.",
    examTip:"On a synoptic map, link each symbol to its weather: cold front → rain and a temperature drop; coastal low → berg winds ahead of it; moisture front → thunderstorms.",
    keyterms:[{w:"Cold front",d:"The leading edge of a cold air mass"},{w:"Berg wind",d:"A hot, dry offshore wind from the interior"},{w:"Moisture front",d:"Boundary between moist and dry air where storms form"}],
    quiz:[
      {q:"Cold fronts mainly bring rain to South Africa's:",opts:["Highveld in summer","South-western Cape in winter","Limpopo in summer","KZN coast in summer"],a:1,et:"Winter rainfall region."},
      {q:"Berg winds are:",opts:["Cold and wet","Hot, dry and offshore","Onshore sea breezes","Tropical cyclones"],a:1,et:"They warm as they descend the escarpment."},
      {q:"After a cold front passes, the temperature ___ and the pressure ___.",opts:["rises, falls","drops, rises","rises, rises","drops, falls"],a:1,et:"Cold, clear air with high pressure follows the front."},
    ],
    conclusion:"Southern Africa's weather repeats its characters. Recognise the cold front, the berg wind and the moisture front, and you can read any forecast."},

  3: {emoji:"🌪️", subtitle:"Grade 12 · The storms that start over warm oceans",
    illusText:"Cyclone Idai crossed the Mozambique Channel in 2019 and devastated Beira.",
    hook:{title:"Cyclone Idai, 2019", body:"In March 2019, Tropical Cyclone Idai made landfall near Beira in Mozambique. Winds, a storm surge and days of flooding killed more than a thousand people across Mozambique, Zimbabwe and Malawi. South Africans sent rescue teams and aid. Tropical cyclones form in the Indian Ocean every summer — understanding them helps the region prepare."},
    intro:"<strong>Tropical cyclones</strong> are intense low-pressure systems that form over warm oceans (above about <strong>26.5 °C</strong>) between roughly 5° and 20° latitude, in late summer. They can't form on the equator because the Coriolis force is too weak to make the air spin. In the Southern Hemisphere they rotate <strong>clockwise</strong>. The calm <strong>eye</strong> is surrounded by the <strong>eye wall</strong>, where winds and rain are most violent. They weaken over land or cooler water because they lose their supply of warm, moist air.",
    concepts:[
      {t:"green", title:"🌡️ What they need", body:"Warm sea (≥ 26.5 °C), moist air, Coriolis force (so not on the equator) and little wind shear high up."},
      {t:"teal", title:"👁️ Structure", body:"Eye: calm, sinking air, clear. Eye wall: towering cumulonimbus, strongest winds. Spiral rain bands around it."},
      {t:"gold", title:"🌊 Hazards", body:"Destructive winds, storm surges, flooding and landslides — and afterwards disease, such as cholera, and food shortages."},
    ],
    examples:[
      {title:"Why not at the equator?", body:"Why do tropical cyclones not form right on the equator?", answer:"The <strong>Coriolis force is almost zero</strong> there, so the air can't start spinning."},
      {title:"Why weaken over land?", body:"Why did Idai weaken after landfall?", answer:"It was <strong>cut off from warm, moist ocean air</strong> (its energy source), and friction with the land slowed the winds."},
      {title:"Impacts", body:"Give two impacts of Idai on Beira.", answer:"<strong>Storm surge and flooding</strong> destroyed homes and infrastructure; afterwards, <strong>cholera outbreaks</strong> and food shortages followed."},
    ],
    mistakes:["Saying Southern Hemisphere cyclones rotate anticlockwise.","Thinking the eye is the most dangerous part — the eye wall is.","Forgetting that most deaths often come from flooding and storm surge, not wind."],
    callout:{title:"Closer to home", body:"Remnants of cyclones can bring heavy rain to Limpopo, Mpumalanga and KZN — Cyclone Eline in 2000 caused severe floods in Mozambique and Limpopo."},
    activity:"Draw a cross-section of a tropical cyclone. Label the eye, eye wall, spiral rain bands, rising and sinking air, and the direction of rotation in the Southern Hemisphere.",
    activityAnswer:"Eye in the centre (sinking air, clear); tall eye-wall clouds on both sides (rising air, heaviest rain, strongest wind); rain bands spreading outwards; rotation clockwise.",
    examTip:"Know the stages of development: tropical disturbance → tropical depression → tropical storm → tropical cyclone → decay. Name the conditions needed at each step.",
    keyterms:[{w:"Eye",d:"The calm centre of a tropical cyclone"},{w:"Storm surge",d:"A rise in sea level pushed onshore by cyclone winds"},{w:"Landfall",d:"When a cyclone's centre moves over land"}],
    quiz:[
      {q:"Tropical cyclones need sea temperatures of at least about:",opts:["16.5 °C","20 °C","26.5 °C","35 °C"],a:2,et:"Warm water provides the energy."},
      {q:"The calm centre of a cyclone is the:",opts:["Eye wall","Eye","Rain band","Front"],a:1,et:"Sinking air makes it calm and clear."},
      {q:"In the Southern Hemisphere, tropical cyclones rotate:",opts:["Clockwise","Anticlockwise","Not at all","East to west only"],a:0,et:"Lows rotate clockwise in the south."},
    ],
    conclusion:"Tropical cyclones are heat engines fed by warm oceans. Know what feeds them and what kills them, and you'll understand their path and their damage."},

  4: {emoji:"🗺️", subtitle:"Grade 10–11 · Why Durban and Port Nolloth live in different worlds",
    illusText:"Two coastal towns at almost the same latitude: one gets about 1 000 mm of rain a year, the other about 60 mm.",
    hook:{title:"Same latitude, different worlds", body:"Durban and Port Nolloth lie at almost the same latitude, both on the coast. Durban is humid and green, with roughly 1 000 mm of rain a year. Port Nolloth, on the Namaqualand coast, gets around 60 mm and is a desert. The difference? The ocean currents beside them — warm on the east coast, cold on the west."},
    intro:"South Africa's climate is shaped by <strong>latitude</strong>, <strong>altitude</strong> (temperature drops about 6.5 °C per 1 000 m), <strong>ocean currents</strong> (the warm <strong>Agulhas</strong> on the east coast, the cold <strong>Benguela</strong> on the west), <strong>distance from the sea</strong> and <strong>pressure systems</strong>. The main climate regions are: Mediterranean (south-western Cape: hot dry summers, wet winters), humid subtropical (KZN coast: hot, wet summers), temperate interior (Highveld: warm wet summers, cold dry winters), semi-desert and desert (Karoo, Namaqualand) and savanna (Limpopo, Lowveld).",
    concepts:[
      {t:"green", title:"🌊 Ocean currents", body:"The warm Agulhas evaporates moisture into onshore winds → rain on the east coast. The cold Benguela cools the air above it → stable air, fog, almost no rain."},
      {t:"teal", title:"⛰️ Altitude", body:"Johannesburg (about 1 750 m) is much cooler than Durban (sea level) — temperature falls about 6.5 °C per 1 000 m."},
      {t:"gold", title:"🏔️ Relief and the escarpment", body:"Moist air forced up the escarpment cools and rains on the windward side; the leeward interior lies in a rain shadow."},
    ],
    examples:[
      {title:"East vs west coast", body:"Why is the west coast so much drier than the east coast?", answer:"The <strong>cold Benguela current</strong> cools the air, making it stable (it doesn't rise) — so little rain, but often fog."},
      {title:"Altitude calculation", body:"How much cooler would you expect Johannesburg (1 750 m) to be than a place at sea level at the same latitude?", answer:"1.75 × 6.5 = about <strong>11 °C cooler</strong>."},
      {title:"Name the region", body:"Hot, dry summers and cool, wet winters.", answer:"<strong>Mediterranean</strong> — the south-western Cape."},
    ],
    mistakes:["Mixing up the currents: Agulhas is warm (east), Benguela is cold (west).","Forgetting altitude when explaining why the Highveld has frost.","Describing a climate without explaining its cause."],
    callout:{title:"Why it matters", body:"Climate decides what can be farmed where: wine and wheat in the Western Cape, sugar cane in KZN, maize on the Highveld, sheep in the Karoo."},
    activity:"Compare Durban, Cape Town, Johannesburg and Upington: for each, give the rainfall season and one factor that explains it.",
    activityAnswer:"Durban: summer (warm Agulhas, onshore winds). Cape Town: winter (cold fronts). Johannesburg: summer thunderstorms (convection, altitude makes winters cold). Upington: very little rain (far inland, under sinking air, rain shadow).",
    examTip:"Always give climate cause-and-effect pairs: “The cold Benguela current cools the air, so it is stable and produces little rain.”",
    keyterms:[{w:"Agulhas current",d:"Warm ocean current along the east coast"},{w:"Benguela current",d:"Cold ocean current along the west coast"},{w:"Rain shadow",d:"Dry area on the leeward side of mountains"}],
    quiz:[
      {q:"The Benguela current is:",opts:["Warm, on the east coast","Cold, on the west coast","Warm, on the west coast","Cold, on the east coast"],a:1,et:"It makes the west coast dry."},
      {q:"A Mediterranean climate has rain mainly in:",opts:["Summer","Winter","Both equally","Never"],a:1,et:"The south-western Cape gets winter rain."},
      {q:"Temperature drops about ___ for every 1 000 m of altitude.",opts:["1 °C","3 °C","6.5 °C","15 °C"],a:2,et:"The environmental lapse rate."},
    ],
    conclusion:"Climate is cause and effect: currents, altitude and pressure systems explain why each part of South Africa feels the way it does."},

  5: {emoji:"🌡️", subtitle:"Grade 11–12 · A warming country and how we respond",
    illusText:"In April 2022, record rainfall caused floods in KwaZulu-Natal that killed more than 400 people.",
    hook:{title:"The 2022 KZN floods", body:"In April 2022, extreme rainfall hit eThekwini and surrounding areas. Floods and landslides killed more than 400 people and destroyed thousands of homes. Scientists found that climate change made such extreme rainfall more likely. Meanwhile, the western half of the country faces longer droughts. Climate change isn't a future problem in South Africa — it's already here."},
    intro:"The <strong>greenhouse effect</strong> keeps Earth warm: gases like carbon dioxide (CO₂) and methane trap outgoing heat. Burning fossil fuels adds more of these gases — the <strong>enhanced greenhouse effect</strong> — causing global warming. South Africa produces most of its electricity from <strong>coal</strong>, making it one of Africa's biggest emitters. Impacts include hotter temperatures, a drier west, more intense storms and floods in the east, and risks to water, farming and health. Responses are <strong>mitigation</strong> (cutting emissions) and <strong>adaptation</strong> (coping with changes that are coming).",
    concepts:[
      {t:"green", title:"🏭 Causes", body:"Coal power, transport fuel, deforestation, cattle and landfills release CO₂ and methane."},
      {t:"teal", title:"🌍 Impacts on SA", body:"More heatwaves, droughts in the west, extreme rain in the east, sea-level rise on the coast, and pressure on maize and water supplies."},
      {t:"gold", title:"🛠️ Mitigation vs adaptation", body:"Mitigation: renewable energy, efficient transport, planting trees. Adaptation: drought-resistant crops, stronger stormwater systems, water saving."},
    ],
    examples:[
      {title:"Mitigation or adaptation?", body:"(a) Building solar farms in the Northern Cape. (b) Planting drought-resistant maize.", answer:"(a) <strong>Mitigation</strong> — it reduces emissions. (b) <strong>Adaptation</strong> — it copes with drier conditions."},
      {title:"Explain the enhanced effect", body:"Why does burning coal warm the planet?", answer:"It releases <strong>CO₂</strong>, which traps more outgoing heat in the atmosphere, raising average temperatures."},
      {title:"Impact on farming", body:"What happened to maize during the 2015–16 drought?", answer:"Harvests fell sharply and South Africa had to <strong>import maize</strong>, pushing up food prices."},
    ],
    mistakes:["Confusing the natural greenhouse effect (good) with the enhanced effect (the problem).","Mixing up mitigation and adaptation.","Saying climate change only means “hotter” — it also means more extreme and unpredictable weather."],
    callout:{title:"A just transition", body:"Moving away from coal must protect jobs in places like Mpumalanga. Planning new work in renewable energy for coal communities is called a just energy transition."},
    activity:"List three ways your school could mitigate climate change and two ways it could adapt.",
    activityAnswer:"Mitigation: solar panels, recycling and composting, walking or lift clubs. Adaptation: rainwater tanks, shade trees and cooler classrooms, water-wise gardens.",
    examTip:"In essays, structure as causes → impacts (environmental, economic, social) → responses (mitigation and adaptation), with South African examples.",
    keyterms:[{w:"Enhanced greenhouse effect",d:"Extra warming caused by human greenhouse gas emissions"},{w:"Mitigation",d:"Reducing the causes of climate change"},{w:"Adaptation",d:"Adjusting to the effects of climate change"}],
    quiz:[
      {q:"The main greenhouse gas released by burning coal is:",opts:["Oxygen","Carbon dioxide","Nitrogen","Ozone"],a:1,et:"CO₂ traps heat."},
      {q:"Planting drought-resistant crops is an example of:",opts:["Mitigation","Adaptation","Deforestation","Emission"],a:1,et:"It helps people cope with changes."},
      {q:"Most of South Africa's electricity comes from:",opts:["Coal","Wind","Nuclear","Hydro"],a:0,et:"Coal-fired power stations dominate."},
    ],
    conclusion:"Climate change is already reshaping South Africa. Know the causes, the impacts and the two kinds of response."},
});

// ─── Module 1: Geomorphology ────────────────────────────────────────────────
_geoAdd('m1', {
  0: {subtitle:"Grade 10–12 · How Earth's landforms are created and shaped",
    hook:{title:"The day Orkney shook", body:"In August 2014, a magnitude 5.5 earthquake struck near Orkney in North West — it was felt as far away as Johannesburg. South Africa sits in the middle of the African Plate, far from plate boundaries, so big quakes are rare here. But the same forces that shake the edges of plates also built the world's mountains, rifts and oceans."},
    examples:[
      {title:"Convergent boundary", body:"What happens where two continental plates collide?", answer:"Rocks are pushed up and <strong>folded</strong> into mountains — the Himalayas formed as India collided with Asia."},
      {title:"Divergent boundary", body:"Give an African example of plates moving apart.", answer:"The <strong>East African Rift Valley</strong>, where the African Plate is slowly splitting."},
      {title:"Transform boundary", body:"What happens where plates slide past each other?", answer:"Stress builds and releases as <strong>earthquakes</strong>, e.g. along the San Andreas Fault in California."},
    ],
    mistakes:["Mixing up the three boundary types.","Saying plates move metres per year — they move a few centimetres.","Thinking South Africa is on a plate boundary."],
    activityAnswer:"Your sketch should show tilted layers with a resistant layer forming a ridge: a steep scarp slope cut across the layers on one side, a gentle dip slope following the layers on the other, and a vale (valley) in the softer rock. The dip direction is along the gentle dip slope.",
    quiz:[
      {q:"Plates moving towards each other form a:",opts:["Divergent boundary","Convergent boundary","Transform boundary","Hot spot"],a:1,et:"Collision builds fold mountains or subduction zones."},
      {q:"The East African Rift Valley is an example of a:",opts:["Divergent boundary","Convergent boundary","Transform boundary","Cuesta"],a:0,et:"The plate is pulling apart."},
      {q:"Tectonic plates typically move about:",opts:["A few centimetres per year","A few metres per year","A kilometre per year","Not at all"],a:0,et:"About as fast as fingernails grow."},
    ],
    conclusion:"Plates move slowly but relentlessly. Their boundaries explain where mountains rise, oceans open and the ground shakes."},

  1: {emoji:"🏜️", subtitle:"Grade 12 · Mesas, buttes and flat-topped hills",
    illusText:"Table Mountain and the Karoo's flat-topped hills share one secret: a hard rock lid.",
    hook:{title:"The lid on Table Mountain", body:"Table Mountain's famous flat top isn't an accident. Its upper layers are hard sandstone that resists erosion, protecting softer rocks beneath. Drive through the Karoo and you'll see the same idea repeated in hundreds of flat-topped hills, each capped by hard rock. Horizontal rock layers create a whole family of landforms — and South Africa has textbook examples."},
    intro:"In <strong>horizontally layered</strong> sedimentary rock, a resistant <strong>cap rock</strong> (such as dolerite or sandstone) protects softer layers (such as shale) beneath. As erosion attacks the edges, a large <strong>plateau</strong> is broken into smaller <strong>mesas</strong> (flat-topped, wider than they are high), then <strong>buttes</strong> (higher than they are wide), and finally small <strong>conical hills</strong> once the cap rock is gone. Steep cliffs form where the cap rock breaks off; gentle <strong>talus</strong> slopes of debris collect below.",
    concepts:[
      {t:"green", title:"🧢 Cap rock", body:"A resistant layer on top slows erosion of everything beneath it. Remove the cap and the hill wears down quickly."},
      {t:"teal", title:"📉 The erosion sequence", body:"Plateau → mesa → butte → conical hill. Each stage is smaller as the cap rock shrinks."},
      {t:"gold", title:"🐑 Human use", body:"Flat tops can be used for grazing and lookouts; steep sides limit roads and farming; talus slopes can be unstable."},
    ],
    examples:[
      {title:"Mesa or butte?", body:"A flat-topped hill is 2 km wide and 300 m high.", answer:"<strong>Mesa</strong> — it is much wider than it is high."},
      {title:"Why flat on top?", body:"Why are Karoo hills flat-topped?", answer:"A <strong>resistant dolerite</strong> cap rock protects the softer sedimentary layers beneath from erosion."},
      {title:"The last stage", body:"What forms when the cap rock has completely eroded?", answer:"A <strong>conical hill</strong> — the soft rock wears into a pointed shape."},
    ],
    mistakes:["Mixing up mesa (wider than high) and butte (higher than wide).","Forgetting to mention the resistant cap rock in explanations.","Putting the erosion sequence in the wrong order."],
    callout:{title:"Look out of the window", body:"On the N1 through the Karoo, you can see plateaus, mesas, buttes and conical hills within a few kilometres of each other."},
    activity:"Sketch the sequence plateau → mesa → butte → conical hill and label the cap rock, cliff and talus slope.",
    activityAnswer:"Each sketch should be smaller than the last, with a flat resistant cap rock on top (except the conical hill), a steep cliff below the cap and a gentle talus slope at the base.",
    examTip:"Exams often give a cross-section and ask you to identify the landform and explain its formation: name the cap rock, the soft rock beneath and the erosion process.",
    keyterms:[{w:"Mesa",d:"A flat-topped hill wider than it is high"},{w:"Butte",d:"A flat-topped hill higher than it is wide"},{w:"Cap rock",d:"A resistant rock layer protecting softer rock beneath"}],
    quiz:[
      {q:"A flat-topped hill that is higher than it is wide is a:",opts:["Mesa","Butte","Plateau","Cuesta"],a:1,et:"Buttes are narrower than mesas."},
      {q:"Karoo hills are capped by resistant:",opts:["Shale","Dolerite","Clay","Sand"],a:1,et:"Dolerite resists erosion."},
      {q:"The correct erosion sequence is:",opts:["Butte → mesa → plateau","Plateau → mesa → butte → conical hill","Conical hill → butte → mesa","Mesa → plateau → butte"],a:1,et:"Landforms shrink as erosion continues."},
    ],
    conclusion:"Hard rock on top, soft rock below — that one idea explains Table Mountain and every flat-topped Karoo hill."},

  2: {emoji:"📐", subtitle:"Grade 12 · Tilted rocks and the ridges they make",
    illusText:"Tilt the layers and erosion carves ridges with one steep side and one gentle side.",
    hook:{title:"The lopsided ridge", body:"Drive past the Magaliesberg near Pretoria and you'll notice the ridge isn't symmetrical: one side is steep, the other slopes gently. That's because the rock layers underneath are <strong>tilted</strong>. The angle of tilt decides what kind of ridge forms — and it affects where farms, roads and towns can go."},
    intro:"When sedimentary layers are <strong>tilted</strong> (inclined), erosion produces ridges with a steep <strong>scarp slope</strong> (cutting across the layers) and a gentler <strong>dip slope</strong> (following the layers). The landform depends on the <strong>angle of dip</strong>: a <strong>cuesta</strong> has a gentle dip (less than about 25°), a <strong>homoclinal ridge</strong> has a dip of about 25°–45°, and a <strong>hogback</strong> has a steep dip (more than about 45°) with both slopes almost equally steep. Softer rock between ridges erodes into valleys called <strong>vales</strong>.",
    concepts:[
      {t:"green", title:"📏 Angle of dip", body:"Gentle dip → cuesta. Medium dip → homoclinal ridge. Steep dip → hogback. The steeper the dip, the more symmetrical the ridge."},
      {t:"teal", title:"⛰️ Scarp vs dip slope", body:"The scarp slope is steep and rocky (rockfalls). The dip slope is gentler, with deeper soils — better for farming."},
      {t:"gold", title:"🛣️ Human use", body:"Roads and railways often follow the vales; dip slopes are farmed; scarp slopes can be quarried but are unstable."},
    ],
    examples:[
      {title:"Name the ridge", body:"Rock layers dip at 15°.", answer:"A <strong>cuesta</strong> — gentle dip."},
      {title:"Name the ridge", body:"Rock layers dip at 60°.", answer:"A <strong>hogback</strong> — both slopes steep."},
      {title:"Where to farm?", body:"Why do farmers prefer the dip slope?", answer:"It is <strong>gentler</strong>, with deeper soils and less risk of rockfalls than the steep scarp slope."},
    ],
    mistakes:["Mixing up the scarp slope and the dip slope.","Forgetting the angle ranges for cuesta, homoclinal ridge and hogback.","Drawing the dip slope cutting across the layers (it follows them)."],
    callout:{title:"Read the map", body:"On a topographic map, a cuesta shows closely spaced contours on one side (scarp) and widely spaced contours on the other (dip slope)."},
    activity:"Draw three cross-sections: layers dipping at 10°, 35° and 70°. Label the landform, scarp slope and dip slope on each.",
    activityAnswer:"10° → cuesta (steep scarp, long gentle dip slope). 35° → homoclinal ridge (both slopes steeper). 70° → hogback (both slopes steep and nearly equal).",
    examTip:"In identification questions, say the dip angle you see and use it to justify the landform name.",
    keyterms:[{w:"Dip slope",d:"The gentle slope that follows the angle of the rock layers"},{w:"Scarp slope",d:"The steep slope cutting across the layers"},{w:"Hogback",d:"A ridge formed by steeply dipping layers (over ~45°)"}],
    quiz:[
      {q:"A cuesta forms where rock layers dip at:",opts:["Less than about 25°","About 50°","Exactly 90°","0°"],a:0,et:"Gentle dip → cuesta."},
      {q:"The steep side of a cuesta is the:",opts:["Dip slope","Scarp slope","Vale","Talus"],a:1,et:"It cuts across the layers."},
      {q:"Which is best suited to farming?",opts:["Scarp slope","Dip slope","Cliff face","Hogback crest"],a:1,et:"Gentler with deeper soils."},
    ],
    conclusion:"Measure the tilt and you can name the ridge. The scarp is steep, the dip slope follows the layers."},

  3: {emoji:"🪨", subtitle:"Grade 12 · How slopes change and when they fail",
    illusText:"Chapman's Peak Drive has been closed many times because rocks fall from the cliffs above it.",
    hook:{title:"Rocks on Chapman's Peak", body:"Chapman's Peak Drive near Cape Town is one of the world's most beautiful roads — and it has been closed many times because rocks fell from the cliffs above. Engineers installed catch fences and canopies to protect drivers. Steep slopes are always slowly changing, and sometimes they fail suddenly. Geographers study why."},
    intro:"A typical hillslope has four <strong>slope elements</strong>: the <strong>crest</strong> (convex, waxing slope at the top), the <strong>cliff</strong> or free face (steep, bare rock), the <strong>talus</strong> or debris slope (fallen rock below the cliff) and the <strong>pediment</strong> (gentle, concave waning slope at the bottom). <strong>Mass movement</strong> is the downslope movement of rock and soil under gravity. Fast types: <strong>rockfall</strong>, <strong>landslide</strong>, <strong>mudflow</strong>. Slower types: <strong>slump</strong> (rotational slip) and <strong>soil creep</strong>. Triggers include heavy rain, steep slopes, removing vegetation, undercutting by roads or rivers, and earthquakes.",
    concepts:[
      {t:"green", title:"🏔️ Slope elements", body:"Crest → cliff → talus → pediment. Each has its own angle and processes."},
      {t:"teal", title:"⚡ Fast vs slow", body:"Rockfalls and mudflows happen in seconds; soil creep is so slow you only see its effects — tilted fences and poles, bent tree trunks."},
      {t:"gold", title:"🌧️ Human triggers", body:"Cutting roads into slopes, removing vegetation and building on steep, saturated ground increase the risk."},
    ],
    examples:[
      {title:"Name the movement", body:"After days of heavy rain, a wet mass of soil and water rushes downhill into homes.", answer:"<strong>Mudflow</strong> — fast, very wet mass movement."},
      {title:"Spot soil creep", body:"Fence posts and telephone poles on a slope lean downhill.", answer:"<strong>Soil creep</strong> — very slow movement of the soil surface."},
      {title:"Why after rain?", body:"Why do slopes often fail after heavy rain?", answer:"Water adds <strong>weight</strong> and reduces <strong>friction</strong> between particles, so the slope can no longer hold."},
    ],
    mistakes:["Mixing up talus (debris) and pediment (gentle base).","Describing soil creep as fast.","Forgetting human causes of slope failure."],
    callout:{title:"Living on slopes", body:"In the 2022 KZN floods, many deaths were caused by mudslides on steep, saturated slopes where homes had been built. Planning where people live saves lives."},
    activity:"Sketch a hillslope and label crest, cliff, talus and pediment. Add one example of a fast and one of a slow mass movement.",
    activityAnswer:"Crest at the top (convex), cliff below it (steep bare rock), talus slope of loose rock, pediment at the base (gentle, concave). Fast: rockfall from the cliff. Slow: soil creep on the pediment or crest.",
    examTip:"For mass-movement questions, cover type, speed, cause (natural and human), impact and management (e.g. retaining walls, drainage, re-vegetation, catch fences).",
    keyterms:[{w:"Talus",d:"Loose rock debris at the base of a cliff"},{w:"Pediment",d:"The gentle, concave slope at the base of a hill"},{w:"Soil creep",d:"Very slow downslope movement of soil"}],
    quiz:[
      {q:"Leaning fence posts on a hillside suggest:",opts:["Rockfall","Soil creep","Mudflow","Landslide"],a:1,et:"Slow movement tilts the posts over time."},
      {q:"The gentle slope at the base of a hill is the:",opts:["Crest","Cliff","Talus","Pediment"],a:3,et:"A concave, waning slope."},
      {q:"Heavy rain increases slope failure because water:",opts:["Adds weight and reduces friction","Makes rock harder","Removes gravity","Cools the slope"],a:0,et:"Saturated slopes are heavier and weaker."},
    ],
    conclusion:"Slopes are always on the move — slowly by creep, suddenly by falls and flows. Know the triggers and how people can reduce the risk."},

  4: {emoji:"🐑", subtitle:"Grade 12 · Layers, dolerite and a dry, fossil-rich land",
    illusText:"In the Valley of Desolation near Graaff-Reinet, dolerite columns tower 120 m over the plains.",
    hook:{title:"The Valley of Desolation", body:"Near Graaff-Reinet, in the Camdeboo National Park, columns of dark rock rise straight up above the Karoo plains. They're made of <strong>dolerite</strong> — molten rock that forced its way between layers of sediment around 180 million years ago, then cooled and hardened. The softer rock around it has eroded away, leaving one of South Africa's most dramatic views."},
    intro:"The <strong>Karoo</strong> is built from the <strong>Karoo Supergroup</strong>: layers of sedimentary rock (shale, mudstone and sandstone) laid down over millions of years. About 180 million years ago, magma intruded these layers as <strong>sills</strong> (horizontal sheets) and <strong>dykes</strong> (vertical walls), cooling into resistant <strong>dolerite</strong>. Because the Karoo is dry, <strong>mechanical weathering</strong> (temperature changes) dominates, and erosion has left mesas, buttes and koppies capped by dolerite. The Karoo is also famous for fossils, including mammal-like reptiles.",
    concepts:[
      {t:"green", title:"🧱 Sills and dykes", body:"Sill: magma squeezed horizontally between layers → flat caps on hills. Dyke: magma in a vertical crack → long narrow ridges."},
      {t:"teal", title:"☀️ Dry-climate weathering", body:"Large day–night temperature differences make rocks expand and contract until they crack and break — exfoliation and block disintegration."},
      {t:"gold", title:"⚖️ Land use", body:"Sheep farming, fossils and tourism, and a heated debate about fracking for shale gas."},
    ],
    examples:[
      {title:"Sill or dyke?", body:"A long, narrow ridge of dolerite runs straight across the plain for kilometres.", answer:"A <strong>dyke</strong> — a vertical intrusion exposed by erosion."},
      {title:"Why flat tops?", body:"Why do many Karoo hills have flat tops?", answer:"<strong>Dolerite sills</strong> form a resistant cap that protects the softer shale and sandstone beneath."},
      {title:"Fracking debate", body:"Give one argument for and one against fracking in the Karoo.", answer:"For: jobs and energy security. Against: risk of <strong>contaminating scarce groundwater</strong> and damaging a fragile environment."},
    ],
    mistakes:["Mixing up sills (horizontal) and dykes (vertical).","Calling dolerite a sedimentary rock — it's igneous.","Saying chemical weathering dominates in the dry Karoo."],
    callout:{title:"A fossil treasure", body:"Karoo rocks hold one of the world's best records of life before the dinosaurs, including the mammal-like reptiles that link reptiles and mammals."},
    activity:"Draw a cross-section showing a dolerite sill and a dyke in Karoo sedimentary layers. Show which landforms each creates after erosion.",
    activityAnswer:"Sill: a horizontal dark band between layers forming the flat cap of a mesa or butte. Dyke: a vertical dark band cutting through layers, standing out as a narrow ridge after the softer rock erodes.",
    examTip:"Link rock type to landform: dolerite (resistant, igneous) → caps and ridges; shale (soft, sedimentary) → eroded plains and vales.",
    keyterms:[{w:"Sill",d:"A horizontal sheet of intruded igneous rock"},{w:"Dyke",d:"A vertical sheet of intruded igneous rock"},{w:"Dolerite",d:"A hard, dark igneous rock common in the Karoo"}],
    quiz:[
      {q:"A horizontal sheet of intruded igneous rock is a:",opts:["Dyke","Sill","Mesa","Cuesta"],a:1,et:"Sills lie between the layers."},
      {q:"Dolerite is:",opts:["A soft sedimentary rock","A hard igneous rock","A type of soil","A fossil"],a:1,et:"It formed from cooled magma."},
      {q:"In the dry Karoo, the main weathering type is:",opts:["Chemical","Mechanical","Biological only","None"],a:1,et:"Temperature changes crack the rock."},
    ],
    conclusion:"The Karoo is layers plus dolerite plus dryness. Those three ingredients explain its landscapes, its fossils and its debates."},

  5: {emoji:"🏔️", subtitle:"Grade 10–12 · The Great Escarpment and South Africa's water tower",
    illusText:"The Drakensberg is South Africa's highest mountain range and the source of water for millions.",
    hook:{title:"South Africa's water tower", body:"The uKhahlamba-Drakensberg is a World Heritage Site for its scenery and its San rock paintings — but it's also a <strong>water tower</strong>. Rivers that start in these mountains supply KZN, and water from the Tugela is pumped over the escarpment to Gauteng. The highest point in South Africa, Mafadi, stands at about 3 450 m on the border with Lesotho."},
    intro:"The <strong>Great Escarpment</strong> is a steep edge that separates South Africa's high interior <strong>plateau</strong> from the lower coastal plains. Its highest and most spectacular section is the <strong>Drakensberg</strong>, where thick layers of <strong>basalt</strong> (from huge lava flows about 180 million years ago) sit on top of sandstone. Rivers erode the edge, so the escarpment slowly <strong>retreats</strong> inland. Its height forces moist air from the Indian Ocean to rise, giving heavy rain and snow on the mountains.",
    concepts:[
      {t:"green", title:"🌋 Built by lava", body:"Basalt lava flows piled up layer on layer, capping older sandstone. Resistant basalt forms the high cliffs."},
      {t:"teal", title:"↩️ Escarpment retreat", body:"Rivers cut back into the escarpment through headward erosion, so the edge slowly moves inland over millions of years."},
      {t:"gold", title:"💧 Water and people", body:"Orographic rain feeds rivers and dams; the Tugela–Vaal transfer scheme moves water over the escarpment to Gauteng."},
    ],
    examples:[
      {title:"Why so much rain?", body:"Why does the Drakensberg get much more rain than the interior behind it?", answer:"Moist air is forced up the escarpment, cools and condenses — <strong>orographic rainfall</strong>. The interior lies in a rain shadow."},
      {title:"Why high cliffs?", body:"Why does the Drakensberg have such steep cliffs?", answer:"Its top layers are <strong>resistant basalt</strong>, which erodes slowly and breaks into vertical cliffs."},
      {title:"Economic value", body:"Give two ways the Drakensberg supports the economy.", answer:"<strong>Water supply</strong> (to KZN and Gauteng) and <strong>tourism</strong> (hiking, rock art, World Heritage Site)."},
    ],
    mistakes:["Thinking the escarpment is a single mountain — it's a long edge.","Forgetting that basalt is volcanic (igneous).","Ignoring the escarpment's role in rainfall and water supply."],
    callout:{title:"Rock art", body:"The Drakensberg holds thousands of San rock paintings, some thousands of years old — one reason it's a World Heritage Site."},
    activity:"Draw a west-to-east cross-section from the interior plateau, over the Drakensberg escarpment, down to the KZN coast. Show where rain falls and label basalt and sandstone.",
    activityAnswer:"High, flat plateau in the west; steep escarpment with basalt cliffs on top and sandstone below; land falling towards the coast in the east. Heavy rain on the eastern (windward) slopes; drier interior in the rain shadow.",
    examTip:"Use precise terms: escarpment, plateau, basalt, headward erosion, orographic rain, rain shadow.",
    keyterms:[{w:"Escarpment",d:"A long, steep slope separating high and low land"},{w:"Basalt",d:"Dark volcanic rock formed from lava"},{w:"Orographic rain",d:"Rain caused by air forced up over mountains"}],
    quiz:[
      {q:"The Drakensberg's top layers are made of:",opts:["Basalt","Shale","Limestone","Granite"],a:0,et:"Ancient lava flows."},
      {q:"Rain caused by air rising over mountains is:",opts:["Convectional","Orographic","Frontal","Cyclonic"],a:1,et:"Relief forces the air up."},
      {q:"The escarpment slowly moves inland because of:",opts:["Headward erosion","Plate collision","Snowfall","Deposition"],a:0,et:"Rivers cut back into its edge."},
    ],
    conclusion:"The escarpment is the edge of the plateau — built by lava, shaped by rivers, and South Africa's most important water source."},
});

